/* Customer Statement: AR invoices, enriched by lookup joins and aged. */ /* Every filter is gated on BOTH its switch and a non-empty value, so a stale */ /* value behind a switched-off toggle cannot leak in, and an unresolved */ /* placeholder degrades to "no filter" instead of "no rows". */ SELECT q.customer_id, q.customer_name, q.ar_invoice_no, q.invoice_date, q.due_date, q.payment_status, q.area_code, q.project_code, q.agent_name, q.payment_term, q.invoice_total_currency, q.invoice_total, q.myr_invoice_total, q.outstanding_amount, q.days_overdue, CASE WHEN q.days_overdue <= 0 THEN q.outstanding_amount ELSE 0 END AS aging_current, CASE WHEN q.days_overdue BETWEEN 1 AND 30 THEN q.outstanding_amount ELSE 0 END AS aging_1_30, CASE WHEN q.days_overdue BETWEEN 31 AND 60 THEN q.outstanding_amount ELSE 0 END AS aging_31_60, CASE WHEN q.days_overdue BETWEEN 61 AND 90 THEN q.outstanding_amount ELSE 0 END AS aging_61_90, CASE WHEN q.days_overdue > 90 THEN q.outstanding_amount ELSE 0 END AS aging_90_plus FROM (SELECT COALESCE(cust.customer_id, '') AS customer_id, COALESCE(cust.customer_com_name, '') AS customer_name, COALESCE(ari.ar_invoice_no, '') AS ar_invoice_no, COALESCE(STRFTIME('%Y-%m-%d', ari.invoice_date), '') AS invoice_date, COALESCE(STRFTIME('%Y-%m-%d', ari.due_date), '') AS due_date, COALESCE(ari.payment_status, '') AS payment_status, COALESCE(ara.area_code, '') AS area_code, COALESCE(pr.project_code, '') AS project_code, COALESCE(ag.agent_name, '') AS agent_name, COALESCE(pt.term_name, '') AS payment_term, COALESCE(ari.invoice_total_currency, '') AS invoice_total_currency, ROUND(COALESCE(ari.invoice_total, 0), 2) AS invoice_total, ROUND(COALESCE(ari.myr_invoice_total, 0), 2) AS myr_invoice_total, ROUND(COALESCE(ari.outstanding_amount, 0), 2) AS outstanding_amount, MAX(COALESCE(CAST((JULIANDAY(COALESCE(p.stmt_date, CURRENT_DATE)) - JULIANDAY(ari.due_date)) AS INTEGER), 0), 0) AS days_overdue FROM ar_invoice AS ari CROSS JOIN (SELECT p0.cust_ids, p0.area_ids, p0.proj_ids, CASE WHEN SUBSTRING_INDEX(p0.dr, ',', 1) = '' THEN NULL WHEN REGEXP_LIKE(SUBSTRING_INDEX(p0.dr, ',', 1), '^[0-9]{13,}$') THEN DATE(UNIX_TO_TIME(CAST(SUBSTRING_INDEX(p0.dr, ',', 1) AS REAL) / 1000)) WHEN REGEXP_LIKE(SUBSTRING_INDEX(p0.dr, ',', 1), '^[0-9]{10,12}$') THEN DATE(UNIX_TO_TIME(SUBSTRING_INDEX(p0.dr, ',', 1))) ELSE DATE(SUBSTRING_INDEX(p0.dr, ',', 1)) END AS date_from, CASE WHEN SUBSTRING_INDEX(p0.dr, ',', -1) = '' THEN NULL WHEN REGEXP_LIKE(SUBSTRING_INDEX(p0.dr, ',', -1), '^[0-9]{13,}$') THEN DATE(UNIX_TO_TIME(CAST(SUBSTRING_INDEX(p0.dr, ',', -1) AS REAL) / 1000)) WHEN REGEXP_LIKE(SUBSTRING_INDEX(p0.dr, ',', -1), '^[0-9]{10,12}$') THEN DATE(UNIX_TO_TIME(SUBSTRING_INDEX(p0.dr, ',', -1))) ELSE DATE(SUBSTRING_INDEX(p0.dr, ',', -1)) END AS date_to, CASE WHEN p0.sd = '' THEN NULL WHEN REGEXP_LIKE(p0.sd, '^[0-9]{13,}$') THEN DATE(UNIX_TO_TIME(CAST(p0.sd AS REAL) / 1000)) WHEN REGEXP_LIKE(p0.sd, '^[0-9]{10,12}$') THEN DATE(UNIX_TO_TIME(p0.sd)) ELSE DATE(p0.sd) END AS stmt_date FROM (SELECT REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(COALESCE(NULLIF('["1001","1002"]', 'null'), ''), '[', ''), ']', ''), '"', ''), '''', ''), ' ', '') AS cust_ids, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(COALESCE(NULLIF('[]', 'null'), ''), '[', ''), ']', ''), '"', ''), '''', ''), ' ', '') AS area_ids, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(COALESCE(NULLIF('[]', 'null'), ''), '[', ''), ']', ''), '"', ''), '''', ''), ' ', '') AS proj_ids, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(COALESCE(NULLIF('["2026-01-01","2026-01-31"]', 'null'), ''), '[', ''), ']', ''), '"', ''), '''', ''), ' ', '') AS dr, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(COALESCE(NULLIF('', 'null'), ''), '[', ''), ']', ''), '"', ''), '''', ''), ' ', '') AS sd) AS p0) AS p LEFT JOIN customer AS cust ON cust.id = ari.customer_id LEFT JOIN area AS ara ON ara.id = ari.area_id LEFT JOIN project AS pr ON pr.id = ari.project_id LEFT JOIN agent AS ag ON ag.id = ari.agent_id LEFT JOIN payment_terms AS pt ON pt.id = ari.payment_term_id WHERE ari.is_deleted = 0 AND ari.organization_id = '7100' AND COALESCE(ari.payment_status, '') <> 'Cancelled' AND ('1' <> '1' OR p.cust_ids = '' OR FIND_IN_SET(CAST(ari.customer_id AS TEXT), p.cust_ids) > 0) AND ('0' <> '1' OR p.area_ids = '' OR FIND_IN_SET(CAST(ari.area_id AS TEXT), p.area_ids) > 0) AND ('0' <> '1' OR p.proj_ids = '' OR FIND_IN_SET(CAST(ari.project_id AS TEXT), p.proj_ids) > 0) AND ('1' <> '1' OR p.date_from IS NULL OR p.date_to IS NULL OR (ari.invoice_date >= p.date_from AND ari.invoice_date < DATE(p.date_to, '1 DAY'))) AND ('0' <> '1' OR p.stmt_date IS NULL OR DATE(ari.invoice_date) = p.stmt_date)) AS q ORDER BY q.customer_id, q.invoice_date, q.ar_invoice_no LIMIT 5000